  '[{"id":"tc1","validation_type":"matching","expected_value":"Reward and upsell premium","description_en":"Champions","description_id":"Champions","points":25},{"id":"tc2","validation_type":"matching","expected_value":"Send a win-back offer","description_en":"At Risk","description_id":"At Risk","points":25},{"id":"tc3","validation_type":"matching","expected_value":"Onboarding nurture","description_en":"New","description_id":"New","points":25},{"id":"tc4","validation_type":"matching","expected_value":"One reactivation try, then stop","description_en":"Lost","description_id":"Lost","points":25}]',
